    if sort_key in BNI_CREDIT_SORTABLE_FIELDS:
        def _sort_value(r):
            if sort_key == "expiry_date":
                return r.get("expiry_date") or r.get("scheduled_end_date")
            if sort_key == "status_key":
                return r.get("status_label")
